{
  "日期": [
    "09月01日",
    "今天的日期，格式为mm月dd日，随故事时间流逝而推进"
  ],
  "星期": [
    "星期五",
    "今天的星期，随日期变化而更新"
  ],
  "时段": [
    "晚上",
    "当前的时间段，可选值为：上午、中午、晚上、深夜。随行动和时间推进更新。"
  ],
  "小鸟游真": {
    "与{{user}}的好感度": [
      20,
      "范围为[0, 200]。{{user}}的鼓励、支持和正面互动会增加好感度(3~7点)，例如送出昂贵礼物或在关键时刻支持她。负面互动、忽视或嘲讽会减少(2~5点)。这是衡量她对{{user}}个人情感的核心指标。"
    ],
    "直播能力": [
      15,
      "范围为[0, 100]。代表小鸟游真的直播技巧、杂谈力、游戏力等综合能力。每次成功完成一次有规划的直播后会少量增加(1~3点)。如果直播中出现精彩操作、神回或重大突破，可获得更多增长(5~10点)。反之，直播事故或长时间不直播可能导致微量减少。数值越高，直播越自信流畅。"
    ],
    "观众人数": [
      200000,
      "代表当前直播间的在线观众数量。这是一个动态值。直播开始时会有一个基础人数。直播能力的提高会增加基础人数。直播中的有趣互动、精彩内容会使其显著增加。反之，无聊、尴尬或事故会导致观众流失。这个数值的变动应在AI的回复中体现出来。"
    ],
    "联系冲动": [
      0,
      "范围[0, 10]。当{{user}}长时间未出现或互动减少时，此数值会随时间缓慢增加(每天+10)。与{{user}}的亲密互动或收到联系后会清零。当数值达到10时，会触发小鸟游真主动联系{{user}}的行为。"
    ],
    "上次直播评价": [
      "还没有直播",
      "用一句话概括上次直播的整体氛围和观众反馈。例如：'一次完美的杂谈回，观众反响热烈' 或 '游戏操作失误较多，气氛有些尴尬'。每次直播结束后更新。"
    ]
  },
  "世界": {
    "剧情触发器": [
      0,
      "用于控制特殊剧情的触发。0:常规状态; 1:触发“切片man速报”论坛更新; 2:触发小鸟游真主动联系{{user}}。此变量由AI根据条件判断更新，并在触发后立即归零。"
    ]
  }
}

